#[component]
pub fn Procurement() -> impl IntoView {
    let tab = RwSignal::new("po");
    view! { <div class="page"><PageHead title=t("Procurement") subtitle="Buy from local and foreign suppliers: requisitions, purchase orders, receipts and bills."/>
        <Tabs tabs=vec![("po", t("Purchase Orders")), ("req", t("Requisitions")), ("grn", t("Goods Receipts")), ("bill", t("Supplier Bills")), ("sup", t("Suppliers"))] active=tab/>
        {move || match tab.get() { "po" => view! { <ListPage cfg=&PO_LIST headless=true/> }.into_any(), "req" => view! { <ListPage cfg=&REQ_LIST headless=true/> }.into_any(), "grn" => view! { <ListPage cfg=&GRN_LIST headless=true/> }.into_any(), "bill" => view! { <ListPage cfg=&BILL_LIST headless=true/> }.into_any(), _ => view! { <ListPage cfg=&SUPPLIERS headless=true/> }.into_any() }}</div> }
}

static NEW_PO: NewDoc = NewDoc { title: "New purchase order", subtitle: "Local orders are in Taka. Import orders need an Incoterm and can be paid by LC or TT.", endpoint: "/purchase-orders", back_label: "Procurement", back_route: "/procurement",
    header: &[ff("supplier_id", "Supplier", FK::Lookup("/suppliers?is_active=true", &["name", "country"])).req(), ff("po_type", "Order type", FK::Select(&[("local", "Local purchase"), ("import", "Import")])).req().def("local"), ff("order_date", "Order date", FK::Date).def("today"), ff("expected_date", "Expected delivery", FK::Date),
        ff("currency", "Currency", FK::Select(CURRENCIES)).req().def("BDT").help("Local orders must be in BDT"), ff("fx_rate", "Exchange rate", FK::Dec).help("Leave empty to use the latest rate"), ff("incoterm", "Incoterm", FK::Select(&[("FOB", "FOB · Free on board"), ("CFR", "CFR · Cost and freight"), ("CIF", "CIF · Cost, insurance, freight"), ("EXW", "EXW · Ex works"), ("CPT", "CPT"), ("CIP", "CIP"), ("DAP", "DAP"), ("DDP", "DDP")])).help("Required for import orders"),
        ff("payment_mode", "Payment", FK::Select(&[("credit", "On credit"), ("cash", "Cash"), ("lc", "Letter of credit"), ("tt", "Telegraphic transfer")])).def("credit"), ff("port_of_loading", "Port of loading", FK::Text), ff("port_of_discharge", "Port of discharge", FK::Text), ff("pi_no", "Proforma invoice no.", FK::Text), ff("pi_date", "Proforma date", FK::Date), ff("discount", "Discount (order currency)", FK::Dec), ff("notes", "Notes", FK::Area).full()],
    lines_title: "Items", lines: &[ff("product_id", "Product", FK::Lookup("/products?is_active=true", &["sku", "name"])).req(), ff("qty", "Quantity", FK::Dec).req(), ff("unit_price", "Unit price", FK::Dec).req()], autofill: None, goto: "/purchase-orders/{rid}", done: "Purchase order saved as a draft", submit_label: "Save draft", min_lines: 1 };
