static PO_DOC: DocCfg = DocCfg {
    endpoint: "/purchase-orders", list_route: "/procurement", list_label: "Procurement", title_key: "po_no", subtitle_key: "supplier_name", status_key: "status", steps: &[("draft", "Draft"), ("pending_approval", "Approval"), ("approved", "Approved"), ("partially_received", "Receiving"), ("received", "Received")],
    facts: &[fact("Type", "po_type", CK::Badge), fact("Order date", "order_date", CK::Date), fact("Expected", "expected_date", CK::Date), fact("Currency", "currency", CK::Text), fact("Exchange rate", "fx_rate", CK::Qty), fact("Incoterm", "incoterm", CK::Text), fact("Payment", "payment_mode", CK::Badge), fact("Proforma", "pi_no", CK::Mono),
        fact("From", "port_of_loading", CK::Text), fact("To", "port_of_discharge", CK::Text), fact("Subtotal", "subtotal", CK::Fc), fact("VAT", "vat_amount", CK::Fc), fact("Total", "total", CK::Fc), fact("Total in Taka", "total_bdt", CK::Money), fact("Created by", "created_by_name", CK::Text), fact("Approved by", "approved_by_name", CK::Text)],
    tables: &[dtable("Items", "lines", &[col("sku", "SKU", CK::Mono), col("product_name", "Product", CK::Text), col("qty", "Qty", CK::Qty), col("unit_price", "Unit price", CK::Qty), col("vat_rate", "VAT %", CK::Pct), col("line_total", "Total", CK::Qty), col("shipped_qty", "Shipped", CK::Qty), col("received_qty", "Received", CK::Qty)])],
    actions: &[
        action("Submit for approval", "/submit", "purchase.write").when(&["draft"]).primary().confirm("Send this order for approval? Orders under the approval limit are approved at once.").done("Submitted"),
        action("Receive goods", "", "inventory.write").when(&["approved", "partially_received"]).primary().abs("/goods-receipts", "po_id").fields(&[ff("warehouse_id", "Warehouse", FK::Lookup("/warehouses", &["name"])).req(), ff("receipt_date", "Date received", FK::Date).def("today")]).lines(LineQty { key: "lines", send: "po_line_id", show: "product_name", total: "qty", done: "received_qty", label: "Received now" }).done("Goods received into stock").goto("/goods-receipts/{rid}"),
        action("Open LC", "", "import.write").when(&["approved", "partially_received"]).abs("/lcs", "po_id").fields(&[ff("bank_account_id", "Issuing bank account", FK::Lookup("/bank-accounts?kind=bank", &["name"])).req(), ff("lc_type", "Type", FK::Select(&[("sight", "At sight"), ("usance", "Usance")])).def("sight"), ff("margin_pct", "Margin %", FK::Dec).def("20"), ff("tolerance_pct", "Tolerance %", FK::Dec).def("5"), ff("expiry_date", "Expiry date", FK::Date).req()]).done("LC drafted").goto("/lcs/{rid}"),
        action("Close order", "/close", "purchase.write").when(&["approved", "partially_received", "received"]).confirm("Close this order? Nothing more will be received against it.").done("Order closed"),
        action("Cancel order", "/cancel", "purchase.write").when(&["draft", "pending_approval", "approved", "rejected"]).danger().confirm("Cancel this order?").done("Order cancelled"),
    ], notes_key: "notes" };
