#[component] pub fn BillPage() -> impl IntoView { let id = use_params_map().with_untracked(|p| p.get("id").unwrap_or_default());
    let extra = Callback::new(|d: serde_json::Value| if matches!(d["status"].as_str(), Some("open") | Some("partial")) && state::can("finance.write") { view! { <div class="alert info"><Icon name="wallet"/><div>"Ready to pay this bill? "<a href="/supplier-payments/new"><b>"Make a payment →"</b></a></div></div> }.into_any() } else { ().into_any() });
    view! { <div class="page"><DocPage cfg=&BILL_DOC id=id extra=extra/></div> } }
